bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Check if the download is an extension without approval and if
  // off-store extension installations are enabled.
  if (download.is_extension && !download.is_approved) {
    return true;
  }

  // Evaluate the danger level based on the file extension.
  const char* file_extension = FilePath_GetExtension(suggested_path);
  if (file_extension && (strcmp(file_extension, ".exe") == 0 ||
                         strcmp(file_extension, ".bat") == 0 ||
                         strcmp(file_extension, ".dll") == 0 ||
                         strcmp(file_extension, ".sh") == 0 ||
                         strcmp(file_extension, ".js") == 0)) {
    return true;
  }

  // If the user did not interact with the hosting page and hasn't visited the
  // referrer before, the download is more likely to be dangerous.
  if (!download.user_gesture && !visited_referrer_before) {
    return true;
  }

  return false;
}

bool IsDangerousDownload(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if it's an extension and if off-store installation is restricted
    if (download.is_extension && !download.has_user_approval) {
        return true;
    }

    // Check the file's danger level based on extension
    const char* file_extension = FilePathGetExtension(suggested_path);
    if (IsExtensionDangerous(file_extension)) {
        return true;
    }

    // If the user hasn't interacted with the page and hasn't visited the referrer before, it's dangerous
    if (!download.has_user_gesture && !visited_referrer_before) {
        return true;
    }

    return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Default to safe
    bool is_dangerous = false;

    // Check if off-store extension installations are enabled and the download is an extension without approval
    if (download.is_extension && !download.is_approved) {
        is_dangerous = true;
    }

    // Evaluate based on file extension
    const char* file_extension = FilePathGetExtension(suggested_path);
    if (file_extension && (StringEquals(file_extension, ".exe") ||
                            StringEquals(file_extension, ".bat") ||
                            StringEquals(file_extension, ".sh") ||
                            StringEquals(file_extension, ".dll") ||
                            StringEquals(file_extension, ".js"))) {
        is_dangerous = true;
    }

    // If the user has not visited the referrer before, increase caution
    if (!visited_referrer_before) {
        is_dangerous = true;
    }

    // No user gesture indicates the download is initiated automatically
    if (!download.has_user_gesture) {
        is_dangerous = true;
    }

    return is_dangerous;
}
